490	---
491	
492	## Best Practices
493	
494	### 1. Always Define Permissions Explicitly
495	
496	```javascript
497	// Good - explicit about being public
498	permissions: false
499	
500	// Good - explicit about requiring auth
501	permissions: true
502	
503	// Bad - missing permissions (will throw error)
504	// permissions: undefined
505	```
506	
507	### 2. Use the Appropriate Pattern
508	
509	| Scenario | Pattern |
510	|----------|---------|
511	| Public endpoint | `permissions: false` |
512	| Standard authenticated CRUD | `permissions: true` |
513	| Need unsafe attrs tracking | `permissions: { unsafeAttrs: [...] }` |
514	| Complex custom logic | `permissions: async function(frame) {...}` |
515	| Need pre-processing | `permissions: { before: async function(frame) {...} }` |
516	
517	### 3. Keep Permission Logic Focused
518	
519	Permission functions should only check permissions, not perform business logic:
520	
521	```javascript
522	// Good - only checks permissions
523	permissions: async function(frame) {
524	  if (!frame.user || frame.user.role !== 'admin') {
525	    throw new NoPermissionError();
526	  }
527	}
528	
529	// Bad - mixes permission check with business logic
530	permissions: async function(frame) {
531	  if (!frame.user) throw new NoPermissionError();
532	
533	  // Don't do this in permissions!
534	  frame.data.processed = true;
535	  await sendNotification(frame.user);
536	}
537	```
538	
539	### 4. Use Meaningful Error Messages
540	
541	```javascript
542	permissions: async function(frame) {
543	  if (!frame.user) {
544	    throw new UnauthorizedError({
545	      message: 'Please log in to access this resource'
546	    });
547	  }
548	
549	  if (frame.user.role !== 'admin') {
550	    throw new NoPermissionError({
551	      message: 'Administrator access required for this operation'
552	    });
553	  }
554	}
555	```
556	
557	### 5. Validate Resource Ownership
558	
559	When resources belong to specific users, always verify ownership:
560	
561	```javascript
562	permissions: async function(frame) {
563	  const resource = await models.Resource.findOne({id: frame.options.id});
564	
565	  if (!resource) {
566	    throw new NotFoundError({message: 'Resource not found'});
567	  }
568	
569	  const isOwner = resource.get('user_id') === frame.user.id;
570	  const isAdmin = frame.user.role === 'admin';
571	
572	  if (!isOwner && !isAdmin) {
573	    throw new NoPermissionError({
574	      message: 'You do not have permission to access this resource'
575	    });
576	  }
577	}
578	```
579	
580	### 6. Use `unsafeAttrs` for Sensitive Fields
581	
582	Mark fields that require elevated permissions:
583	
584	```javascript
585	permissions: {
586	  unsafeAttrs: [
587	    'author_id',    // Only admins should change authorship
588	    'status',       // Publishing requires special permission
589	    'visibility',   // Changing visibility is restricted
590	    'featured'      // Only editors can feature content
591	  ]
592	}
593	```
594	
595	---
596	
597	## Error Types
598	
599	Use appropriate error types from `@tryghost/errors`:
600	
601	- **UnauthorizedError** - User is not authenticated
602	- **NoPermissionError** - User is authenticated but lacks permission
603	- **NotFoundError** - Resource doesn't exist (use carefully to avoid information leakage)
604	- **ValidationError** - Input validation failed
605	
606	```javascript
607	const {
608	  UnauthorizedError,
609	  NoPermissionError,
610	  NotFoundError
611	} = require('@tryghost/errors');
612	```
613	
614	---
615	
616	## Adding Permissions via Migrations
617	
618	When creating a new API endpoint that uses the default permission handler (`permissions: true`), you need to add permissions to the database. Ghost provides utilities to make this easy.
619	
620	### Migration Utilities
621	
622	Import the permission utilities from `ghost/core/core/server/data/migrations/utils`:
623	
624	```javascript
625	const {combineTransactionalMigrations, addPermissionWithRoles} = require('../../utils');
626	```
627	
628	### Example: Adding CRUD Permissions for a New Resource
629	
630	```javascript
631	// ghost/core/core/server/data/migrations/versions/X.X/YYYY-MM-DD-HH-MM-SS-add-myresource-permissions.js
632	
633	const {combineTransactionalMigrations, addPermissionWithRoles} = require('../../utils');
634	
635	module.exports = combineTransactionalMigrations(
636	    addPermissionWithRoles({
637	        name: 'Browse my resources',
638	        action: 'browse',
639	        object: 'my_resource'  // Singular form of docName
640	    }, [
641	        'Administrator',
642	        'Admin Integration'
643	    ]),
644	    addPermissionWithRoles({
645	        name: 'Read my resources',
646	        action: 'read',
647	        object: 'my_resource'
648	    }, [
649	        'Administrator',
650	        'Admin Integration'
651	    ]),
652	    addPermissionWithRoles({
653	        name: 'Edit my resources',
654	        action: 'edit',
655	        object: 'my_resource'
656	    }, [
657	        'Administrator',
658	        'Admin Integration'
659	    ]),
660	    addPermissionWithRoles({
661	        name: 'Add my resources',
662	        action: 'add',
663	        object: 'my_resource'
664	    }, [
665	        'Administrator',
666	        'Admin Integration'
667	    ]),
668	    addPermissionWithRoles({
669	        name: 'Delete my resources',
670	        action: 'destroy',
671	        object: 'my_resource'
672	    }, [
673	        'Administrator',
674	        'Admin Integration'
675	    ])
676	);
677	```
678	
679	### Available Roles
680	
681	Common roles you can assign permissions to:
682	
683	- **Administrator** - Full admin access
684	- **Admin Integration** - API integrations with admin scope
685	- **Editor** - Can manage all content
686	- **Author** - Can manage own content
687	- **Contributor** - Can create drafts only
688	- **Owner** - Site owner (inherits all Administrator permissions)
689	
690	### Permission Naming Conventions
691	
692	- **name**: Human-readable, e.g., `'Browse automated emails'`
693	- **action**: The API method - `browse`, `read`, `edit`, `add`, `destroy`
694	- **object**: Singular form of `docName` - `automated_email` (not `automated_emails`)
695	
696	### Restricting to Administrators Only
697	
698	To make an endpoint accessible only to administrators (not editors, authors, etc.), only assign permissions to:
699	- `Administrator`
700	- `Admin Integration`
701	
702	```javascript
703	addPermissionWithRoles({
704	    name: 'Browse sensitive data',
705	    action: 'browse',
706	    object: 'sensitive_data'
707	}, [
708	    'Administrator',
709	    'Admin Integration'
710	])
711	```
712	

