const assert = require('node:assert/strict');
const sinon = require('sinon');
const supertest = require('supertest');
const testUtils = require('../../utils');
const localUtils = require('./utils');
const config = require('../../../core/shared/config');

describe('Audit Logs API', function () {
    let request;

    before(async function () {
        await localUtils.startGhost();
        request = supertest.agent(config.get('url'));
        await localUtils.doAuth(request, 'integrations', 'api_keys');
    });

    after(async function () {
        sinon.restore();
    });

    it('Can browse audit logs', async function () {
        // Create a post to generate an audit log entry
        const res = await request
            .post(localUtils.API.getApiQuery('posts/'))
            .set('Origin', config.get('url'))
            .send({
                posts: [{
                    title: 'test post for audit log'
                }]
            })
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(201);

        const postId = res.body.posts[0].id;

        // Browse audit logs
        const res2 = await request
            .get(localUtils.API.getApiQuery('audit_logs/'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(200);

        localUtils.API.checkResponse(res2.body, 'actions');
        assert.ok(res2.body.actions);
        assert.ok(res2.body.actions.length > 0);
    });

    it('Can browse audit logs with pagination', async function () {
        const res = await request
            .get(localUtils.API.getApiQuery('audit_logs/?limit=5&page=1'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(200);

        localUtils.API.checkResponse(res.body, 'actions');
        assert.ok(res.body.actions);
        assert.ok(res.body.meta);
        assert.ok(res.body.meta.pagination);
    });

    it('Can read a single audit log by id', async function () {
        // First, get an audit log ID
        const browseRes = await request
            .get(localUtils.API.getApiQuery('audit_logs/?limit=1'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect(200);

        const auditLogId = browseRes.body.actions[0].id;

        // Read the specific audit log
        const res = await request
            .get(localUtils.API.getApiQuery(`audit_logs/${auditLogId}/`))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect('Cache-Control', testUtils.cacheRules.private)
            .expect(200);

        localUtils.API.checkResponse(res.body, 'actions');
        assert.equal(res.body.actions[0].id, auditLogId);
    });

    it('Returns 401 for unauthenticated requests', async function () {
        const unauthRequest = supertest.agent(config.get('url'));

        await unauthRequest
            .get(localUtils.API.getApiQuery('audit_logs/'))
            .set('Origin', config.get('url'))
            .expect('Content-Type', /json/)
            .expect(401);
    });
});

