const ghostBookshelf = require('./base');

const AuditLog = ghostBookshelf.Model.extend({
    tableName: 'actions',

    defaults: function defaults() {
        return {};
    }
}, {
    orderDefaultOptions: function orderDefaultOptions() {
        return {
            created_at: 'DESC'
        };
    },

    permittedOptions(methodName) {
        const options = ghostBookshelf.Model.permittedOptions.call(this, methodName);
        const validOptions = {
            findPage: ['page', 'limit', 'filter']
        };

        if (validOptions[methodName]) {
            options.push(...validOptions[methodName]);
        }

        return options;
    }
});

module.exports = {
    AuditLog: ghostBookshelf.model('AuditLog', AuditLog)
};

